<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/business_microsite_v1130.php';$bid=(int)($_GET['business_id']??0);$token=trim((string)($_GET['token']??''));$b=sk1130_business($bid);if(!$b){http_response_code(404);exit('Business not found.');}$name=(string)sk1130_business_value($b,['name'],'Business');$logo=(string)sk1130_business_value($b,['logo_url','logo','image_url','image'],'');$conv=$token!==''?sk1180_conversation_by_token($bid,$token):[];$messages=$conv?sk1180_messages((int)$conv['id'],150):[];$quotes=$conv?sk1180_quotes($bid,(int)$conv['contact_id'],30):[];?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Chat with <?=sk1130_h($name)?></title><link rel="stylesheet" href="/assets/business-crm-v1180.css?v=1180"></head><body class="crm-public"><main class="crm1180 public"><header class="public-head"><a href="/business-site.php?id=<?=$bid?>">← Business website</a><div><?php if($logo):?><img src="<?=sk1130_h($logo)?>" alt=""><?php endif;?><h1><?=sk1130_h($name)?></h1><p>Chat, ask a question or request a quotation.</p></div></header><section class="chat-card"><div class="messages" id="messages"><?php foreach($messages as $m):?><article class="msg <?=sk1130_h($m['sender_type'])?>"><small><?=sk1130_h($m['sender_type'])?> · <?=sk1130_h($m['created_at'])?></small><p><?=nl2br(sk1130_h($m['message']))?></p></article><?php endforeach;?><?php if(!$messages):?><div class="empty">Start a conversation with <?=sk1130_h($name)?>.</div><?php endif;?></div><form id="chatForm"><input type="hidden" name="business_id" value="<?=$bid?>"><input type="hidden" name="token" id="token" value="<?=sk1130_h($token)?>"><input class="hp" name="company_website" tabindex="-1" autocomplete="off"><?php if(!$conv):?><div class="grid"><label>Name<input required name="customer_name" maxlength="160"></label><label>Phone<input name="phone" maxlength="60"></label><label>Email<input type="email" name="email" maxlength="190"></label></div><?php endif;?><label>Message<textarea required name="message" rows="4" maxlength="4000" placeholder="Ask about availability, service, product or request a price quotation…"></textarea></label><button>Send message</button><span id="status"></span></form></section><?php if($quotes):?><section class="quotes"><h2>Your quotations</h2><?php foreach($quotes as $q):?><article><div><b><?=sk1130_h($q['quote_no'])?></b><span><?=sk1130_h($q['status'])?></span></div><h3><?=sk1130_h($q['title'])?></h3><strong>PKR <?=number_format((float)$q['total_amount'],0)?></strong><?php if($q['valid_until']):?><small>Valid until <?=sk1130_h($q['valid_until'])?></small><?php endif;?></article><?php endforeach;?></section><?php endif;?></main><script>const f=document.getElementById('chatForm'),s=document.getElementById('status');f.addEventListener('submit',async e=>{e.preventDefault();s.textContent='Sending…';try{const r=await fetch('/api/business-chat-v1180.php',{method:'POST',body:new FormData(f)}),j=await r.json();if(!j.ok)throw new Error(j.error||'Could not send');const u=new URL(location.href);u.searchParams.set('token',j.token);location.href=u.toString()}catch(x){s.textContent=x.message}});</script></body></html>